def transform(grid):
    """Overlay matching-sized regions split by a centered solid divider; shared marks become 2."""
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if r and h - r - 1 == r and len(set(row)) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                    for ra, rb in zip(top, bottom)]
    for c in range(w):
        if c and w - c - 1 == c and all(grid[y][c] == grid[0][c] for y in range(h)):
            return [[2 if row[x] != 0 and row[c + 1 + x] != 0 else 0
                     for x in range(c)] for row in grid]
    raise ValueError("expected a centered solid divider")

